// Define GOD2_LEGACY_CHARACTER_LIST_STANDALONE_TEST for a standalone executable.
#include "protocol/LegacyCharacterListCandidate.h"
#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <numeric>
#include <stdexcept>

namespace {
// Independent literal transcription of the historical EMPTY logical frame,
// not generated by the candidate and not decoded from a historical fixed wire.
// OfficialServerSelectionWire.cs provenance is pinned in the candidate header.
// SHA-256: 1E087135069D6891DD725F8CF00FB41C591F829EDC1CEA0577CA6B4E36B09567
constexpr std::array<std::uint8_t, 78> expected_logical{
    0x4e, 0x00, 0x07, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x02, 0x03, 0x00, 0x20, 0x00, 0x11, 0x14, 0x01, 0x60, 0x01,
    0x20, 0x01, 0x20, 0x81, 0x20, 0x04, 0x00, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xf7,
};

void check(bool condition, const char* message) {
    if (!condition) {
        throw std::runtime_error(message);
    }
}
}

void test_legacy_character_list_candidate() {
    using god2::LegacyCharacterListCandidate;
    using god2::recovered_zero_seed_key;
    constexpr auto logical = LegacyCharacterListCandidate::decoded();
    constexpr auto wire = LegacyCharacterListCandidate::wire();
    static_assert(logical.size() == 78 && wire.size() == 78);
    check(logical == expected_logical, "independent historical logical fixture");
    check(logical[0] + 256u * logical[1] == 78, "little-endian total length");
    check(logical[2] == 0x07, "logical opcode");
    check(logical[3] == 0, "zero uint8 character count");
    check(logical[4] == 0, "separate flags byte is zero (including bit 0)");
    const auto zero = [](std::uint8_t byte) { return byte == 0; };
    check(std::all_of(logical.begin() + 5, logical.begin() + 21, zero), "empty first name");
    check(std::all_of(logical.begin() + 41, logical.begin() + 57, zero), "empty second name");
    check(std::all_of(logical.begin() + 41, logical.begin() + 77, zero), "zero second slot");
    const auto checksum = (std::accumulate(logical.begin(), logical.end() - 1, 0u)
                           + 77u * 0x3cu) & 0xffu;
    check(checksum == 0xf7 && logical.back() == checksum, "sum checksum including header");

    check(wire[0] == 78 && wire[1] == 0, "untransformed length header");
    // Direct formula against independent plain bytes checks every wire byte;
    // this does not depend only on an encoder/decoder round trip.
    for (std::size_t i = 2; i < wire.size(); ++i) {
        const unsigned previous = i == 2 ? 0u : expected_logical[i - 1];
        const auto expected = ((expected_logical[i] ^ recovered_zero_seed_key[i - 2])
                               + previous + 253u) & 0xffu;
        check(wire[i] == expected, "current key, prior plaintext, modulo-256 transform");
    }
    check(wire[2] == 0x04, "zero initial feedback, not historical 0xAF");
    check(wire[3] == 0x04 && wire[4] == 0xfd, "plaintext feedback and underflow");
    check(wire[18] == 0xba, "nonzero key begins at key[16], frame[18]");
    check(wire.back() == 0x11, "checksum is transformed with key[75]");

    auto decoded = wire;
    unsigned previous = 0;
    for (std::size_t i = 2; i < decoded.size(); ++i) {
        const auto plain = ((static_cast<unsigned>(wire[i]) + 259u - previous) & 0xffu)
                           ^ recovered_zero_seed_key[i - 2];
        decoded[i] = static_cast<std::uint8_t>(plain);
        previous = plain;
    }
    check(decoded == expected_logical, "independent inverse transform including checksum");
    check(LegacyCharacterListCandidate::wire() == wire, "feedback resets on each call");
    std::cout << "PASS: historical EMPTY layout/checksum and current zero-seed transform; "
                 "candidate UNVERIFIED for current-client acceptance.\n";
}

#ifdef GOD2_LEGACY_CHARACTER_LIST_STANDALONE_TEST
int main() { test_legacy_character_list_candidate(); }
#endif
